        ],
        "responses" => [
            "si" => "පරිවාස හා ළමාරක්ෂක සේවා දෙපාර්තමේන්තුව — පුරවැසි ප්‍රඥප්තිය\n\n\"අපගේ බැඳීම ඔබට සේවය කිරීමයි.\"\n\nබාහිර සේවා දායක ඔබ සඳහා — ළමා ආරක්ෂාව, පරිවාස, දරුකමට ගැනීම, ආධාර, ලියාපදිංචිය හා පුනරුත්ථාපනය සේවා 14ක් ලබා දේ.\n\n\"සේවාලාභී මහජන ඔබගෙන් ඉදිරිපත්වන යෝජනා අපි සතුටින් භාර ගනිමු.\"\n\nWebsite: https://probcc.nw.gov.lk",
            "en" => "Department of Probation & Child Care Services — Citizens' Charter\n\n\"Our commitment is to serve you.\"\n\nExternal services for citizens — 14 services covering child protection, probation, legal adoption, assistance, registration, and rehabilitation.\n\n\"We gladly welcome suggestions from service recipients.\"\n\nWebsite: https://probcc.nw.gov.lk",
            "ta" => "நன்னடத்தை மற்றும் குழந்தை பராமரிப்பு சேவைகள் துறை — குடிமக்கள் சாசனம்\n\n\"உங்களுக்கு சேவை செய்வதே எங்கள் உறுதிமொழி.\"\n\nகுடிமக்களுக்கான வெளிப்புற சேவைகள் — குழந்தை பாதுகாப்பு, பரோல், தத்தெடுத்தல், உதவி, பதிவு மற்றும் மறுவாழ்வு உள்ளிட்ட 14 சேவைகள்.\n\n\"சேவை பெறுபவர்களின் பரிந்துரைகளை மகிழ்ச்சியுடன் ஏற்றுக்கொள்கிறோம்.\"\n\nWebsite: https://probcc.nw.gov.lk"
