            "si" => "පරිවාස හා ළමාරක්ෂක — බාහිර සේවා 14:\n\n01. ළමා නිවාසගත කිරීම\n• අවශ්‍ය: ඉල්ලීම් ලිපිය; අධිකරණ නියෝගය (අනුව)\n• නීති: 1941/22, 1939/48 | කාලය: දින 07\n\n02. භාරකාරත්වයට පත් කිරීම\n• අවශ්‍ය: වාචික/ලිඛිත දැනුම් දීම; පොලිසිය විසින් අධිකරණයට යොමු කළ ළමයෙකු\n• නීති: 1939/48 | කාලය: අධිකරණ නියෝගයට අනුකූලව\n\n03. සහතික පාසල්ගත කිරීම\n• අවශ්‍ය: වයස 12–16; පාලනය කළ නොහැකි; ළමා වරදකරු හෝ භාරකරු ඉල්ලීම\n• නීති: 1939/48 | කාලය: මාස 03\n\n04. ළමා නිවාසගත ළමයකු සමාජගත කිරීම\n• අවශ්‍ය: දෙමාපිය/භාරකරු ඉල්ලීම් ලිපිය\n• නීති: අධිකරණ නියෝගය, කොමසාරිස් අනුමැතිය | කාලය: දින 15\n\n05. නිත්‍යානුකූල දරුකමට ගැනීම\n• අවශ්‍ය: ඉල්ලීම් ලිපිය, උප්පැන්න/ජා.හැ.පිටපත්, ග්‍රාම නිලධාරී සහතිකය, වැටුප්/ආදායම් සහතිකය ආදිය\n• නීති: 1941/24 | කාලය: මාස 02\n\n06. නිවුන්දරු ආධාර\n• අවශ්‍ය: ඉල්ලීම් ලිපිය, අයදුම්පත්, උප්පැන්න සහතික, ග්‍රාම නිලධාරී/ප්‍රා.ලේ. වාර්තා\n• නීති: 2017/01 චක්‍රලේඛය | කාලය: මාස 01\n\n07. අධ්‍යාපන පෝෂණ ආධාර (අඩු ආදායම්)\n• අවශ්‍ය: ඉල්ලීම් ලිපිය, පරිවාස නිර්දේශ, උප්පැන්න ඡායා පිටපත්, ග්‍රාම නිලධාරී සහතිකය, විදුහල්පති තහවුරුව\n• නීති: ත්‍රිපුද්ගල කමිටු, කොමසාරිස් අනුමැතිය | කාලය: මාස 01\n\n08. අධ්‍යාපන උපකරණ කට්ටල\n• අවශ්‍ය: ස්ථානභාර පරිවාස නිලධාරී නිර්දේශ සහිත අයදුම්පත්\n• කාලය: මාස 03\n\n09. වරදකරු පුනරුත්ථාපනය\n• අවශ්‍ය: අධිකරණ නියෝගය\n• නීති: 1944/42 | කාලය: අධිකරණ නියෝගය අනුව\n\n10. ස්වේච්ඡා ළමා නිවාස ලියාපදිංචිය\n• අවශ්‍ය: ඉල්ලුම්පත්, සංවිධාන ලියාපදිංචි සහතිකය, ඉඩම්/ගොඩනැගිල්ල, බී ආකෘතිය, අවම ප්‍රමිති\n• නීති: 1941/22 | කාලය: මාස 02\n\n11. ස්වේච්ඡා ළමා නිවාස නඩත්තු ආධාර\n• අවශ්‍ය: අයදුම්, ඉල්ලීම්, පොදු 35, පරි.ල.සේ.39–43, බැංකු ප්‍රකාශ\n• නීති: 6/2/අමා/2016/131 (2016.11.02) | කාලය: මාස 01\n\n12. දිවා සුරැකුම් මධ්‍යස්ථාන ලියාපදිංචිය\n• අවශ්‍ය: ජාතික මාර්ගෝපදේශ අනුව ඉල්ලුම්පත්, ඉඩම් අයිතිය\n• නීති: ශ්‍රී ලංකා ළමා දිවා සුරැකුම් ජාතික මාර්ගෝපදේශ | කාලය: මාස 01\n\n13. දිවා සුරැකුම් මධ්‍යස්ථාන නඩත්තු ආධාර\n• අවශ්‍ය: ලියාපදිංචි මධ්‍යස්ථානය; පොදු 35, (එෆ්/2/එස්.ඒ)11/74\n• නීති: වප/03/දී.සු.ම/පොදු 98/05/13 චක්‍රලේඛය | කාලය: දින 15\n\n14. දිවා සුරැකුම් හා ළමා නිවාස යථායෝග්‍යාධාර\n• අවශ්‍ය: ස්ථානභාර පරිවාස නිලධාරී නිර්දේශ සහිත ඉල්ලුම්පත්\n• නීති: කොමසාරිස් අනුමැතිය | කාලය: මාස 03\n\nසෑම සේවාවක්ම: කොමසාරිස්, ජ්‍යෙෂ්ඨ පරිවාස නිලධාරී, මූලස්ථාන පරිවාස නිලධාරී.",
            "en" => "Probation & Child Care — 14 External Services:\n\n01. Child placement in children's home\n• Requirements: Application letter; court order (if applicable)\n• Legal: Ordinance 22/1941, 48/1939 | Time: 7 days\n\n02. Assigning child to suitable guardian\n• Requirements: Oral/written notice; child referred to court by police for care & protection\n• Legal: Ordinance 48/1939 | Time: Per court order\n\n03. Certified school placement\n• Requirements: Age 12–16; unruly child; juvenile offender or guardian rehabilitation request\n• Legal: Ordinance 48/1939 | Time: 3 months\n\n04. Reintegration of institutionalized child\n• Requirements: Parent/guardian application letter\n• Legal: Court order, Commissioner approval | Time: 15 days\n\n05. Legal adoption\n• Requirements: Application letter, birth cert copies, NIC copies, GN certificate, salary/income cert (income > Rs.20,000/month), medical reports if no children\n• Legal: Adoption Ordinance 24/1941 | Time: 2 months\n\n06. Twins assistance\n• Requirements: Application letter, form, children's birth certificates, low-income GN cert, Divisional Secretary report with probation recommendation, identity documents\n• Legal: Circular 2017/01 | Time: 1 month\n\n07. Educational nutrition assistance (low-income families)\n• Requirements: Application letter, probation officer report, birth cert copies, GN low-income cert, principal confirmation for school child\n• Legal: Tripartite committee, Commissioner approval | Time: 1 month\n\n08. School equipment kit\n• Requirements: Application with station probation officer recommendation\n• Time: 3 months\n\n09. Offender rehabilitation\n• Requirements: Court order\n• Legal: Ordinance 42/1944 | Time: Per court order\n\n10. Registration of voluntary children's home\n• Requirements: Application, org registration cert, land/building docs, building plan, Form B, minimum standards compliance\n• Legal: Ordinance 22/1941 | Time: 2 months\n\n11. Maintenance support for registered children's home\n• Requirements: Application, request letter, Public 35 voucher, Forms Par.L.S.39–43, prior year bank statements\n• Legal: Circular 6/2/Am/2016/131 (02.11.2016) | Time: 1 month\n\n12. Daycare centre registration\n• Requirements: Application per National Guidelines, land ownership/occupancy documents\n• Legal: Sri Lanka Child Daycare National Guidelines | Time: 1 month\n\n13. Maintenance support for registered daycare\n• Requirements: Must be registered; Public 35 voucher & Form (F/2/SA)11/74\n• Legal: Circular vap/03/disuma/pub 98/05/13 | Time: 15 days\n\n14. Appropriate grants for daycare & children's homes\n• Requirements: Application with station probation officer recommendation\n• Legal: Commissioner approval | Time: 3 months\n\nOfficers for all services: Commissioner, Senior Probation Officer, Head Office Probation Officer.",
            "ta" => "பரோல் & குழந்தை பராமரிப்பு — 14 வெளிப்புற சேவைகள்:\n\n01. குழந்தை மக்கள் இல்லத்தில் வைப்பு\n• தேவை: விண்ணப்ப கடிதம்; நீதிமன்ற உத்தரவு (பொருந்தினால்)\n• சட்டம்: 1941/22, 1939/48 | நேரம்: 7 நாட்கள்\n\n02. பொருத்தமான பாதுகாவலருக்கு ஒப்படைத்தல்\n• தேவை: வாய்மொழி/எழுத்து அறிவிப்பு; போலீஸ் நீதிமன்றத்திற்கு அனுப்பிய குழந்தை\n• சட்டம்: 1939/48 | நேரம்: நீதிமன்ற உத்தரவு படி\n\n03. சான்றளிக்கப்பட்ட பாடசालை வைப்பு\n• தேவை: வயது 12–16; கட்டுப்படுத்த முடியாத; இளம் குற்றவாளி அல்லது பாதுகாவலர் கோரிக்கை\n• சட்டம்: 1939/48 | நேரம்: 3 மாதங்கள்\n\n04. நிறுவன குழந்தை சமூகமயமாக்கல்\n• தேவை: பெற்றோர்/பாதுகாவலர் விண்ணப்ப கடிதம்\n• சட்டம்: நீதிமன்ற உத்தரவு, கமிஷனர் ஒப்புதல் | நேரம்: 15 நாட்கள்\n\n05. சட்டபூர்வ தத்தெடுத்தல்\n• தேவை: விண்ணப்ப கடிதம், பிறப்பு/தேசிய அடையாள நகல்கள், கிராம அலுவலர் சான்று, வருமான சான்று (மாதம் Rs.20,000+) போன்றவை\n• சட்டம்: 1941/24 | நேரம்: 2 மாதங்கள்\n\n06. இரட்டைக் குழந்தை உதவி\n• தேவை: விண்ணப்பம், படிவம், பிறப்பு சான்றுகள், குறைந்த வருமான GN சான்று, பிரதேச செயலாளர் அறிக்கை\n• சட்டம்: சுற்றறிக்கை 2017/01 | நேரம்: 1 மாதம்\n\n07. கல்வி ஊட்டச்சத்து உதவி (குறைந்த வருமானம்)\n• தேவை: விண்ணப்பம், பரோல் அலுவலர் அறிக்கை, பிறப்பு நகல்கள், GN சான்று, பாடசாலை முதல்வர் உறுதிப்படுத்தல்\n• சட்டம்: மூன்று தரப்பு குழு, கமிஷனர் ஒப்புதல் | நேரம்: 1 மாதம்\n\n08. கல்வி உபகரண தொகுப்பு\n• தேவை: நிலைய பரோல் அலுவலர் பரிந்துரையுடன் விண்ணப்பம்\n• நேரம்: 3 மாதங்கள்\n\n09. குற்றவாளி மறுவாழ்வு\n• தேவை: நீதிமன்ற உத்தரவு\n• சட்டம்: 1944/42 | நேரம்: நீதிமன்ற உத்தரவு படி\n\n10. தன்னார்வ குழந்தை இல்ல பதிவு\n• தேவை: விண்ணப்பம், அமைப்பு பதிவு, நில/கட்டிட ஆவணங்கள், திட்டம், படிவம் B, குறைந்தபட்ச தரநிலை\n• சட்டம்: 1941/22 | நேரம்: 2 மாதங்கள்\n\n11. பதிவு செய்யப்பட்ட குழந்தை இல்ல பராமரிப்பு உதவி\n• தேவை: விண்ணப்பம், பொது 35, படிவங்கள் Par.L.S.39–43, வங்கி அறிக்கைகள்\n• சட்டம்: சுற்றறிக்கை 6/2/Am/2016/131 | நேரம்: 1 மாதம்\n\n12. பகல் பராமரிப்பு மைய பதிவு\n• தேவை: தேசிய வழிகாட்டுதல்கள் படி விண்ணப்பம், நில உரிமை ஆவணங்கள்\n• சட்டம்: இலங்கை குழந்தை பகல் பராமரிப்பு தேசிய வழிகாட்டுதல்கள் | நேரம்: 1 மாதம்\n\n13. பதிவு செய்யப்பட்ட பகல் பராமரிப்பு பராமரிப்பு உதவி\n• தேவை: பதிவு செய்யப்பட்ட மையம்; பொது 35, படிவம் (F/2/SA)11/74\n• சட்டம்: சுற்றறிக்கை vap/03/disuma/pub 98/05/13 | நேரம்: 15 நாட்கள்\n\n14. பகல் பராமரிப்பு & குழந்தை இல்லங்களுக்கு பொருத்தமான மானியங்கள்\n• தேவை: நிலைய பரோல் அலுவலர் பரிந்துரையுடன் விண்ணப்பம்\n• சட்டம்: கமிஷனர் ஒப்புதல் | நேரம்: 3 மாதங்கள்\n\nஅனைத்து சேவைகளுக்கும்: கமிஷனர், மூத்த பரோல் அலுவலர், தலைமையக பரோல் அலுவலர்."
        ]
