            "si" => "ළමා ආරක්ෂණ හා පරිවාස සේවා (01–04):\n\n• සේවාව: ළමයෙකු ළමා නිවාසගත කිරීම\n  අවශ්‍යතා: ඉල්ලීම් ලිපිය; අධිකරණ නියෝගය (අනුව)\n  නීති: 1941 අංක 22, 1939 අංක 48 | කාලය: දින 07\n\n• සේවාව: සුදුසු භාරකාරත්වයට පත් කිරීම\n  අවශ්‍යතා: වාචික/ලිඛිත දැනුම් දීම; භාරය හා ආරක්ෂාව අවශ්‍ය ළමයෙකු බවට පොලිසිය විසින් අධිකරණයට යොමු කිරීම\n  නීති: 1939 අංක 48 | කාලය: අධිකරණ නියෝගයට අනුකූලව\n\n• සේවාව: සහතික පාසල්ගත කිරීම\n  අවශ්‍යතා: වයස 12–16; පාලනය කළ නොහැකි; ළමා වරදකරු හෝ භාරකරු පුනරුත්ථාපන ඉල්ලීම\n  නීති: 1939 අංක 48 | කාලය: මාස 03\n\n• සේවාව: ළමා නිවාසගත ළමයකු සමාජගත කිරීම\n  අවශ්‍යතා: දෙමාපිය/භාරකරු ඉල්ලීම් ලිපිය\n  නීති: අධිකරණ නියෝගය, කොමසාරිස් අනුමැතිය | කාලය: දින 15\n\nනිලධාරීන්: කොමසාරිස්, ජ්‍යෙෂ්ඨ පරිවාස නිලධාරී, මූලස්ථාන පරිවාස නිලධාරී",
