            "ta" => "தன்னார்வ குழந்தை இல்ல பதிவு & பராமரிப்பு உதவி (10–11):\n\n• சேவை: தன்னார்வ குழந்தை இல்ல பதிவு\n  தேவை: விண்ணப்பம், அமைப்பு பதிவு சான்று, நில உரிமை ஆவணங்கள், கட்டிடத் திட்டம், படிவம் B, குறைந்தபட்ச தரநிலை இணக்கம்\n  சட்டம்: 1941 இல் 22 ஆம் எண் அனாதை இல்லங்கள் சட்டம் | நேரம்: 2 மாதங்கள்\n\n• சேவை: பதிவு செய்யப்பட்ட தன்னார்வ குழந்தை இல்ல பராமரிப்பு உதவி\n  தேவை: விண்ணப்பம், கோரிக்கை கடிதம், பொது 35 வவுச்சர், படிவங்கள் Par.L.S.39–43, கடந்த ஆண்டு வங்கி அறிக்கைகள்\n  சட்டம்: சுற்றறிக்கை 6/2/Am/2016/131 (02.11.2016) | நேரம்: 1 மாதம்\n\nஅலுவலர்கள்: கமிஷனர், மூத்த பரோல் அலுவலர், தலைமையக பரோல் அலுவலர்"
